style.css:
@-moz-document domain("miro.com") {
/* Main infinite board background */
  canvas {
    filter: invert(1) hue-rotate(180deg) brightness(0.82) contrast(0.9) !important;
  }

  /* Make empty board/grid dark */
  div[class*="viewport"],
  div[class*="board"],
  div[class*="grid"],
  div[class*="canvas"] {
    background: #0d1117 !important;
  }

  /* Keep UI/toolbars dark */
  div[class*="toolbar"],
  div[class*="sidebar"],
  div[class*="panel"],
  div[class*="menu"] {
    background: #161b22 !important;
    color: white !important;
  }

  /* White icons */
  svg,
  svg *,
  i,
  i * {
    fill: white !important;
    stroke: white !important;
  }
}
